157		if err := s.RegisterPart("part1", 10); err != nil {
158			t.Fatalf("register part: %v", err)
159		}
160		// rNoProduct 关联尚未登记的产品；rNoPart 关联已登记产品但备件缺失。
161		if err := s.SubmitRequest("rNoProduct", "pMissing", "F"); err != nil {
162			t.Fatalf("submit: %v", err)
163		}
164		if err := s.SubmitRequest("rNoPart", "p1", "F"); err != nil {
165			t.Fatalf("submit: %v", err)
166		}
167	
168		// 产品缺失：已知请求的失败历史可查，资格与库存依据明确为空。
169		if _, err := s.Reserve("c1", "rNoProduct", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrNotFound) {
