330		h[0].Error = HistoryErrorConflict
331		h[0].Eligibility.Reasons = append(h[0].Eligibility.Reasons, ReasonWarrantyExpired)
332		h[0].StockBasis.Committable = 999
333		h2, _ := s.RequestHistory("r1")
