16	// rvSnapSetup 构造用户给出的主例：保修三十天、故障 NOISE 未被除外（除外清单
17	// 含另一代码 FAULTX）的产品；备件初始库存十件；保修期内预留四件、到期时刻
18	// （保修后第十五天）晚于保修截止时刻，并已成功使用一件。
19	func rvSnapSetup(t *testing.T) (s *Store, deadline, commitExpiry, justPast time.Time) {
20		t.Helper()
21		purchase := t0
22		deadline = purchase.Add(30 * day)
23		commitExpiry = purchase.Add(45 * day)
24		// 产品刚过保、承诺尚未到期的查看时刻。
