27		s = NewStore()
28		if err := s.RegisterProduct("p1", purchase, 30, []string{"FAULTX"}); err != nil {
29			t.Fatalf("register product: %v", err)
30		}
31		if err := s.RegisterPart("part1", 10); err != nil {
32			t.Fatalf("register part: %v", err)
33		}
34		if err := s.SubmitRequest("r1", "p1", "NOISE"); err != nil {
35			t.Fatalf("submit request: %v", err)
36		}
37		if _, err := s.Reserve("c1", "r1", "part1", 4, commitExpiry, purchase.Add(10*day)); err != nil {
38			t.Fatalf("reserve c1: %v", err)
39		}
40		if _, err := s.Use("u1", "c1", 1, purchase.Add(12*day)); err != nil {
