46	// assertExpiredOnlyBasis 断言资格依据为登记内容、在过保时刻只有过保一项拒绝
47	// 原因：不合格、未命中除外，购买时刻、保修天数与保修截止时刻仍是登记依据。
48	func assertExpiredOnlyBasis(t *testing.T, e *Eligibility, purchase, deadline time.Time) {
49		t.Helper()
