76	// assertC1Snapshot 断言承诺明细为 c1 的真实内容：归属 r1/part1、原数量四件，
77	// 已用/未用与状态按各次查询时刻给定。
78	func assertC1Snapshot(t *testing.T, d CommitmentDetail, used, remaining int, status CommitmentStatus, commitExpiry time.Time) {
