221			t.Fatalf("reserve c-five: %v", err)
222		}
223		if _, err := s.Reserve("c-four", "req-four", partIsolationPartID, 4, expFour, nowOK); err != nil {
224			t.Fatalf("reserve c-four: %v", err)
225		}
226		if _, err := s.Use("u-five-2", "c-five", 2, nowOK); err != nil {
227			t.Fatalf("use 2 from c-five: %v", err)
228		}
229	
230		saved, err := s.PartStatus(partIsolationPartID, nowOK)
231		if err != nil {
232			t.Fatalf("saved part status: %v", err)
233		}
234		assertPartIsoAccount(t, saved, 10, 7, 3)
235	
236		// 从四件那笔承诺再使用一件：实物 9，有效占用 6（3+3），可承诺 3。
237		later := t0.Add(11 * day)
238		if _, err := s.Use("u-four-1", "c-four", 1, later); err != nil {
239			t.Fatalf("use 1 from c-four: %v", err)
240		}
241		// 取消五件那笔承诺：只释放其未用的 3 件，已用 2 件不补回实物。
242		if _, err := s.Cancel("c-five", later); err != nil {
243			t.Fatalf("cancel c-five: %v", err)
244		}
245	
246		// 最新查询：实物 9、有效占用 3、可承诺 6。
247		latest, err := s.PartStatus(partIsolationPartID, later)
248		if err != nil {
249			t.Fatalf("latest part status: %v", err)
250		}
251		assertPartIsoAccount(t, latest, 9, 3, 6)
252		if len(latest.Details) != 2 {
253			t.Fatalf("latest details = %d, want 2", len(latest.Details))
254		}
255		// 取消的明细仍保留原定 5、已用 2、未用 3 并显示 canceled。
256		assertDetailFact(t, mustDetailByID(t, latest.Details, "c-five"), "req-five", 5, 2, 3, CommitmentCanceled, expFive)
257		// 另一笔显示原定 4、已用 1、未用 3，仍有效。
258		assertDetailFact(t, mustDetailByID(t, latest.Details, "c-four"), "req-four", 4, 1, 3, CommitmentActive, expFour)
259	
260		// 先前保存的结果仍是十、七、三，以及当时两笔承诺的数量与 active 状态。
261		assertPartIsoAccount(t, saved, 10, 7, 3)
262		if len(saved.Details) != 2 {
263			t.Fatalf("saved details = %d, want 2", len(saved.Details))
264		}
265		assertDetailFact(t, mustDetailByID(t, saved.Details, "c-five"), "req-five", 5, 2, 3, CommitmentActive, expFive)
266		assertDetailFact(t, mustDetailByID(t, saved.Details, "c-four"), "req-four", 4, 0, 4, CommitmentActive, expFour)
267	
268		// 仓库事实与最新查询一致：取消不抹掉已用数量，实物不补回。
269		cFive, _ := s.Commitment("c-five")
270		if !cFive.Canceled || cFive.Quantity != 5 || cFive.Used != 2 || cFive.Unused() != 3 {
271			t.Fatalf("stored c-five: %+v", cFive)
272		}
273		cFour, _ := s.Commitment("c-four")
274		if cFour.Canceled || cFour.Quantity != 4 || cFour.Used != 1 || cFour.Unused() != 3 {
275			t.Fatalf("stored c-four: %+v", cFour)
276		}
277		p, _ := s.Part(partIsolationPartID)
278		if p.Stock != 9 {
279			t.Fatalf("physical stock = %d, want 9", p.Stock)
280		}
281	}
282	
283	// TestPartStatusEmptyDetailsSnapshotStaysEmpty 没有承诺时已登记备件的明细
284	// 为空，实物剩余与可承诺数量相同；后来正常预留成功，新查询出现承诺明细，
285	// 先前取得的空结果仍保持为空，其库存数字也不随后续使用或预留改写。
286	func TestPartStatusEmptyDetailsSnapshotStaysEmpty(t *testing.T) {
287		s := partIsoStore(t, "req-later")
288	
289		empty, err := s.PartStatus(partIsolationPartID, nowOK)
290		if err != nil {
291			t.Fatalf("empty part status: %v", err)
292		}
293		if empty.PhysicalRemaining != 12 || empty.ActiveOccupied != 0 || empty.Committable != 12 {
294			t.Fatalf("empty account: %+v, want phys=12 occupied=0 committable=12", empty)
295		}
296		if len(empty.Details) != 0 {
297			t.Fatalf("empty details = %d, want 0", len(empty.Details))
298		}
299	
300		// 后来正常预留成功（时刻仍早于到期时刻）：新查询出现承诺明细。
301		expLater := partIsoExpiry(40)
302		if _, err := s.Reserve("c-later", "req-later", partIsolationPartID, 5, expLater, nowOK); err != nil {
303			t.Fatalf("reserve c-later: %v", err)
304		}
305		if _, err := s.Use("u-later-2", "c-later", 2, nowOK); err != nil {
306			t.Fatalf("use 2 from c-later: %v", err)
307		}
308		latest, err := s.PartStatus(partIsolationPartID, nowOK)
309		if err != nil {
310			t.Fatalf("latest part status: %v", err)
311		}
312		if latest.PhysicalRemaining != 10 || latest.ActiveOccupied != 3 || latest.Committable != 7 {
313			t.Fatalf("latest account: phys=%d occupied=%d committable=%d, want 10/3/7",
314				latest.PhysicalRemaining, latest.ActiveOccupied, latest.Committable)
315		}
316		if len(latest.Details) != 1 {
317			t.Fatalf("latest details = %d, want 1", len(latest.Details))
318		}
319		assertDetailFact(t, latest.Details[0], "req-later", 5, 2, 3, CommitmentActive, expLater)
320	
321		// 先前的空结果仍保持为空，三项数字也保留当时内容。
322		if len(empty.Details) != 0 {
323			t.Fatalf("earlier empty result gained details: %+v", empty.Details)
324		}
325		if empty.PhysicalRemaining != 12 || empty.ActiveOccupied != 0 || empty.Committable != 12 {
326			t.Fatalf("earlier empty result account changed: phys=%d occupied=%d committable=%d, want 12/0/12",
327				empty.PhysicalRemaining, empty.ActiveOccupied, empty.Committable)
328		}
329	}
