216	// TestReserveHonorsRegistrationSnapshot 除外清单隔离要落到备件预留结果上：
217	// 备件存在且数量足够、到期时刻合法时，原除外请求仍返回现有的不合格错误，
218	// 不创建承诺、不占用备件；未被登记清单除外的请求（含后来替换或补入的
219	// 代码）仍可正常预留。
220	func TestReserveHonorsRegistrationSnapshot(t *testing.T) {
221		codes := []string{"BROKEN_SEAL"}
222		s := isolationStore(t, codes)
223		mustSubmit(t, s, "rExcl", "BROKEN_SEAL")
224		mustSubmit(t, s, "rReplaced", "NOISE")
225		mustSubmit(t, s, "rAdded", "LEAK")
226	
227		// 登记后替换原清单代码并补入新代码，再尝试预留。
228		codes[0] = "NOISE"
229		codes = append(codes, "LEAK")
230		p, _ := s.Product("p1")
231		p.ExcludedCodes["LEAK"] = struct{}{}
232		delete(p.ExcludedCodes, "BROKEN_SEAL")
233	
234		// 原除外请求：仍返回 ErrIneligible，错误明确列出故障除外原因。
235		_, err := s.Reserve("c-bad", "rExcl", "part1", 2, expiryOK, nowOK)
236		if !errors.Is(err, ErrIneligible) {
237			t.Fatalf("reserve excluded request: got %v, want ErrIneligible", err)
238		}
239		if !strings.Contains(err.Error(), string(ReasonFaultExcluded)) {
240			t.Fatalf("error %q must list fault_code_excluded", err.Error())
241		}
242		// 不创建承诺。
243		if _, err := s.Commitment("c-bad"); !errors.Is(err, ErrNotFound) {
244			t.Fatalf("failed reserve created commitment: %v", err)
245		}
246		// 不占用备件。
247		st, _ := s.PartStatus("part1", nowOK)
248		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 0 || st.Committable != 10 {
249			t.Fatalf("failed reserve occupied stock: %+v", st)
250		}
251		// 失败留痕，且历史中的资格快照仍显示除外。
252		h, _ := s.RequestHistory("rExcl")
253		if len(h) != 1 || h[0].Success || h[0].Error != HistoryErrorIneligible {
254			t.Fatalf("ineligible history: %+v", h)
255		}
256		if h[0].Eligibility == nil || !h[0].Eligibility.Excluded ||
257			len(h[0].Eligibility.Reasons) != 1 ||
258			h[0].Eligibility.Reasons[0] != ReasonFaultExcluded {
259			t.Fatalf("ineligible history snapshot: %+v", h[0].Eligibility)
260		}
261	
262		// 替换/补入进来、原先未被除外的代码：正常预留，各占用 2 件。
263		for _, tc := range []struct{ commit, request string }{
264			{"c-replaced", "rReplaced"},
265			{"c-added", "rAdded"},
266		} {
267			c, err := s.Reserve(tc.commit, tc.request, "part1", 2, expiryOK, nowOK)
268			if err != nil {
269				t.Fatalf("reserve %s: %v", tc.request, err)
270			}
271			if c.Quantity != 2 || c.Used != 0 {
272				t.Fatalf("commitment for %s: %+v", tc.request, c)
273			}
274		}
275		st2, _ := s.PartStatus("part1", nowOK)
276		if st2.PhysicalRemaining != 10 || st2.ActiveOccupied != 4 || st2.Committable != 6 {
277			t.Fatalf("eligible reserves stock math: %+v", st2)
278		}
279	}
