281	// TestEmptyExclusionListStaysEmpty 产品以空除外清单登记后，向取回的集合
282	// （或登记入参）加入代码，不能让该产品开始拒绝这个故障。
283	func TestEmptyExclusionListStaysEmpty(t *testing.T) {
284		input := make([]string, 0, 4)
285		s := isolationStore(t, input)
286		mustSubmit(t, s, "r1", "RETROACTIVELY_ADDED")
287	
288		retrieved, _ := s.Product("p1")
289		retrieved.ExcludedCodes["RETROACTIVELY_ADDED"] = struct{}{}
290		input = append(input, "RETROACTIVELY_ADDED")
291	
292		again, _ := s.Product("p1")
293		if len(again.ExcludedCodes) != 0 {
294			t.Fatalf("empty exclusion list gained codes: %+v", again.ExcludedCodes)
295		}
296		assertEligibleInWindow(t, s, "r1")
